k;font-size:18px;margin:8px 0}.badge{display:inline-block;background:#dcfce7;color:#166534;padding:7px 10px;border-radius:20px;font-weight:700;font-size:13px}@media(max-width:800px){.hero,.app{grid-template-columns:1fr}.side{display:none}.grid,.stats{grid-template-columns:1fr 1fr}h1{font-size:38px}.nav a:not(.btn){display:none}.main{padding:20px}}@media(max-width:480px){.grid,.stats{grid-template-columns:1fr}}
</style></head><body>
