<?php else:?><div class="app"><aside class="side"><div class="brand">DataSell</div><?php foreach(['dashboard'=>'Overview','data'=>'Buy Data','airtime'=>'Airtime','bills'=>'Bills','exam'=>'Exam Pins','wallet'=>'Fund Wallet','transactions'=>'Transactions','profile'=>'Profile'] as $k=>$v):?><a href="?page=<?=$k?>"><?=$v?></a><?php endforeach?><?php if($u['is_admin']):?><a href="?page=admin">Admin</a><?php endif?><form method="post"><input type="hidden" name="action" value="logout"><button class="btn secondary" style="margin-top:20px">Logout</button></form></aside><main class="main"><h2><?=esc(ucwords(str_replace('-',' ',$page)))?></h2><?php if($msg):?><div class="alert"><?=esc($msg)?></div><?php endif?><?php if($err):?><div class="alert error"><?=esc($err)?></div><?php endif?>
<?php if($page==='dashboard'):?><p>Welcome back, <?=esc($u['fullname'])?>.</p><div class="stats"><div class="card"><span>Wallet balance</span><div class="value">₦<?=number_format($u['wallet_balance'],2)?></div></div><div class="card"><span>Account</span><div class="value"><?=$u['is_admin']?'Admin':'Customer'?></div></div><div class="card"><span>Status</span><div class="value">Active</div></div></div><div class="grid"><?php foreach(['data'=>'Buy Data','airtime'=>'Airtime','bills'=>'Pay Bills','exam'=>'Exam Pins','wallet'=>'Fund Wallet','transactions'=>'History'] as $k=>$v):?><a class="card service" href="?page=<?=$k?>"><b><?=$v?></b><p>Open service</p></a><?php endforeach?></div>
