<?php elseif($page==='transactions'):$s=db()->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC LIMIT 100');$s->execute([$u['id']]);?><div class="card" style="overflow:auto"><table class="table"><tr><th>Type</th><th>Amount</th><th>Status</th><th>Reference</th><th>Date</th></tr><?php foreach($s as $t):?><tr><td><?=esc($t['type'])?></td><td>₦<?=number_format($t['amount'],2)?></td><td><?=esc($t['status'])?></td><td><?=esc($t['reference'])?></td><td><?=esc($t['created_at'])?></td></tr><?php endforeach?></table></div>
