<?php elseif($page==='admin'&&$u['is_admin']):$rs=db()->query("SELECT f.*,u.email FROM funding_requests f JOIN users u ON u.id=f.user_id ORDER BY f.id DESC LIMIT 100");?><div class="card" style="overflow:auto"><h3>Funding requests</h3><table class="table"><tr><th>User</th><th>Amount</th><th>Status</th><th>Action</th></tr><?php foreach($rs as $r):?><tr><td><?=esc($r['email'])?></td><td>₦<?=number_format($r['amount'],2)?></td><td><?=esc($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn primary">Approve</button></form><?php endif?></td></tr><?php endforeach?></table></div><?php endif?></main></div><?php endif?></body></html>